INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','future-forms','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"future-forms","title":"Future plans, predictions and arrangements","level":"A2","order":28,"summary":"Choose a future form by the speaker’s intention: a decision, a plan, an arrangement or a timetable.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Decisions and promises","Prior intentions","Arranged future events","Timetables and future time clauses"],"rules":[{"title":"Decisions and promises","explanation":"Use **will + base verb** for a decision made while speaking, a promise or a prediction. Will does not change with the subject. A time word such as tomorrow does not force will: the speaker’s meaning matters more than the date. In conversation, I will often becomes I’ll.","pattern":"I **will help**. / She **will not help**.","commonMistakes":["Do not add -s after will: she will helps is not the standard form."],"examples":["Make a promise with will: I **will prepare** the visitor guide tomorrow.","Make a promise with will: I **will restore** the old portrait tomorrow."],"skill":"form"},{"title":"Prior intentions","explanation":"Use **be going to + base verb** for an intention formed before speaking. The form of be agrees with the subject. Going to also introduces a prediction based on present evidence. A dark sky can justify It is going to rain, even if no one planned the rain.","pattern":"We **are going to leave**.","commonMistakes":["Going to and will can overlap. These questions explicitly name the construction rather than treating both as universally incompatible."],"examples":["Complete the prior plan using going to: We **are going to prepare** the visitor guide next week.","Complete the prior plan using going to: We **are going to restore** the old portrait next week."],"skill":"meaning"},{"title":"Arranged future events","explanation":"The present continuous can describe a future arrangement, especially when another person, place or booking is involved. A future time expression separates this use from an action happening now. Present continuous is not a general replacement for will in predictions.","pattern":"We **are meeting** the guide tomorrow.","commonMistakes":["It is raining tomorrow is unusual as a simple weather prediction; use a suitable prediction form."],"examples":["Use the present continuous for a booked arrangement: She **is preparing** the visitor guide on Tuesday.","Use the present continuous for a booked arrangement: She **is restoring** the old portrait on Tuesday."],"skill":"contrast"},{"title":"Timetables and future time clauses","explanation":"Use present simple for published timetables. After when, as soon as, before and until in an ordinary future time clause, use a present form. The main clause can contain will. This rule concerns time clauses, not indirect questions about what will happen.","pattern":"I’ll call **when I arrive**.","commonMistakes":["I wonder when she will arrive is an indirect question, so will is possible there."],"examples":["Keep the when-clause in the present simple: I will call when I **prepare** the visitor guide.","Keep the when-clause in the present simple: I will call when I **restore** the old portrait."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"653df896-7b8f-52e7-ada5-4b70191ba1bf","topicSlug":"future-forms","level":"A2","prompt":"Make a promise with will: I ____ the visitor guide tomorrow.","choices":[{"id":"A","text":"will preparing"},{"id":"B","text":"will prepared"},{"id":"C","text":"will prepare"},{"id":"D","text":"will to prepare"}],"answerId":"C","hint":"The instruction asks for a promise with **will**. Check the form immediately after the modal.","explanation":"A promise uses **will + prepare**. The modal already marks the future meaning; keep the main verb in its base form.","keywords":["will-form"],"skill":"will-form","contextKey":"future-forms-1","fingerprint":"3201aaa848608c871c20ffca87dfa53e876797cf979b2b4860a4419ef1567077","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The instruction asks for a promise with **will**. Check the form immediately after the modal.","A promise uses **will + prepare**. The modal already marks the future meaning; keep the main verb in its base form.","Choose **will prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form cannot follow will alone; a continuous form would need be.","B":"A past form cannot directly follow will.","C":"A promise uses **will + prepare**. The modal already marks the future meaning; keep the main verb in its base form.","D":"Will takes a bare infinitive, without to."}}},{"id":"0a5115ec-d41d-558e-a381-8e32d1d23864","topicSlug":"future-forms","level":"A2","prompt":"Complete the prior plan using going to: We ____ the visitor guide next week.","choices":[{"id":"A","text":"is going to prepare"},{"id":"B","text":"are going to preparing"},{"id":"C","text":"going to prepare"},{"id":"D","text":"are going to prepare"}],"answerId":"D","hint":"Find the subject, then build **be going to + base verb**.","explanation":"With **we**, use **are going to + prepare** for the stated prior plan.","keywords":["going-to-form"],"skill":"going-to-form","contextKey":"future-forms-1","fingerprint":"c6e81755a9f154b789f6b51ccfa2b89afd51fede107be7382c7028cb3bd45817","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the subject, then build **be going to + base verb**.","With **we**, use **are going to + prepare** for the stated prior plan.","Choose **are going to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Is does not agree with we.","B":"To in this intention pattern takes the base verb, not -ing.","C":"The finite verb are is missing.","D":"With **we**, use **are going to + prepare** for the stated prior plan."}}},{"id":"ac3a07e2-87e3-50bc-aaaf-814cb7c3adf0","topicSlug":"future-forms","level":"A2","prompt":"Use the present continuous for a booked arrangement: She ____ the visitor guide on Tuesday.","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"is preparing"},{"id":"C","text":"are preparing"},{"id":"D","text":"is prepare"}],"answerId":"B","hint":"A future time can accompany a present continuous arrangement. Check subject + be + -ing.","explanation":"The arrangement is expressed with **is + preparing**; Tuesday gives it future reference.","keywords":["arrangement"],"skill":"arrangement","contextKey":"future-forms-1","fingerprint":"a0d9e92f1c9c0dab3c852531331b2238617d007ad76eef2fdfa8b59d7710d1b6","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A future time can accompany a present continuous arrangement. Check subject + be + -ing.","The arrangement is expressed with **is + preparing**; Tuesday gives it future reference.","Choose **is preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The finite auxiliary is is missing.","B":"The arrangement is expressed with **is + preparing**; Tuesday gives it future reference.","C":"Are does not agree with she.","D":"The present continuous needs the -ing form after is."}}},{"id":"054d5ad4-816b-53f3-a490-2904ec2079e5","topicSlug":"future-forms","level":"A2","prompt":"Keep the when-clause in the present simple: I will call when I ____ the visitor guide.","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"to prepare"},{"id":"C","text":"prepare"},{"id":"D","text":"will prepare"}],"answerId":"C","hint":"Locate **when**. The future marker belongs in the main clause, while this time clause uses present simple.","explanation":"The ordinary future time clause after **when** uses present simple: **I prepare**.","keywords":["future-time-clause"],"skill":"future-time-clause","contextKey":"future-forms-1","fingerprint":"b7bfc0112498f94f10cf99d324864ae4741c1a894165726dfe48f558688e94ef","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Locate **when**. The future marker belongs in the main clause, while this time clause uses present simple.","The ordinary future time clause after **when** uses present simple: **I prepare**.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form alone is not a finite verb for I in this clause.","B":"An infinitive cannot serve as the finite verb after when I.","C":"The ordinary future time clause after **when** uses present simple: **I prepare**.","D":"This ordinary when time clause uses a present form, not will."}}},{"id":"00220277-e7be-50a9-a606-aa6bac67e36a","topicSlug":"future-forms","level":"A2","prompt":"Make a promise with will: I ____ the old portrait tomorrow.","choices":[{"id":"A","text":"will restoring"},{"id":"B","text":"will restored"},{"id":"C","text":"will restore"},{"id":"D","text":"will to restore"}],"answerId":"C","hint":"The instruction asks for a promise with **will**. Check the form immediately after the modal.","explanation":"A promise uses **will + restore**. The modal already marks the future meaning; keep the main verb in its base form.","keywords":["will-form"],"skill":"will-form","contextKey":"future-forms-2","fingerprint":"8d4227a2939369ceaf74c535178a089fa249bc7285bb5d45ddf7ca3e78aa6ec6","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The instruction asks for a promise with **will**. Check the form immediately after the modal.","A promise uses **will + restore**. The modal already marks the future meaning; keep the main verb in its base form.","Choose **will restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form cannot follow will alone; a continuous form would need be.","B":"A past form cannot directly follow will.","C":"A promise uses **will + restore**. The modal already marks the future meaning; keep the main verb in its base form.","D":"Will takes a bare infinitive, without to."}}},{"id":"a0e7619f-23fc-5745-a97a-b0783bd42d82","topicSlug":"future-forms","level":"A2","prompt":"Complete the prior plan using going to: We ____ the old portrait next week.","choices":[{"id":"A","text":"are going to restoring"},{"id":"B","text":"going to restore"},{"id":"C","text":"are going to restore"},{"id":"D","text":"is going to restore"}],"answerId":"C","hint":"Find the subject, then build **be going to + base verb**.","explanation":"With **we**, use **are going to + restore** for the stated prior plan.","keywords":["going-to-form"],"skill":"going-to-form","contextKey":"future-forms-2","fingerprint":"dac34fab0d781e5aae299fb7aedf939309f7cd4414ccea39401a4881e5285507","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the subject, then build **be going to + base verb**.","With **we**, use **are going to + restore** for the stated prior plan.","Choose **are going to restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"To in this intention pattern takes the base verb, not -ing.","B":"The finite verb are is missing.","C":"With **we**, use **are going to + restore** for the stated prior plan.","D":"Is does not agree with we."}}},{"id":"4f276fba-0bd6-5673-a78d-e4cd9cb4434e","topicSlug":"future-forms","level":"A2","prompt":"Use the present continuous for a booked arrangement: She ____ the old portrait on Tuesday.","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"is restoring"},{"id":"C","text":"are restoring"},{"id":"D","text":"is restore"}],"answerId":"B","hint":"A future time can accompany a present continuous arrangement. Check subject + be + -ing.","explanation":"The arrangement is expressed with **is + restoring**; Tuesday gives it future reference.","keywords":["arrangement"],"skill":"arrangement","contextKey":"future-forms-2","fingerprint":"f65735c74ae0c9eaeca7cbe1887b0a34350679b9a01169715fbdc6e8c00081bc","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A future time can accompany a present continuous arrangement. Check subject + be + -ing.","The arrangement is expressed with **is + restoring**; Tuesday gives it future reference.","Choose **is restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The finite auxiliary is is missing.","B":"The arrangement is expressed with **is + restoring**; Tuesday gives it future reference.","C":"Are does not agree with she.","D":"The present continuous needs the -ing form after is."}}},{"id":"80b918ea-ca0a-50d2-aaf6-ec73257b3d5e","topicSlug":"future-forms","level":"A2","prompt":"Keep the when-clause in the present simple: I will call when I ____ the old portrait.","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restore"},{"id":"C","text":"will restore"},{"id":"D","text":"restoring"}],"answerId":"B","hint":"Locate **when**. The future marker belongs in the main clause, while this time clause uses present simple.","explanation":"The ordinary future time clause after **when** uses present simple: **I restore**.","keywords":["future-time-clause"],"skill":"future-time-clause","contextKey":"future-forms-2","fingerprint":"e1e4262704d68a3afe3daf2d4b93a890e4e79c7b88fb3e71a21aade2b6c21d72","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Locate **when**. The future marker belongs in the main clause, while this time clause uses present simple.","The ordinary future time clause after **when** uses present simple: **I restore**.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An infinitive cannot serve as the finite verb after when I.","B":"The ordinary future time clause after **when** uses present simple: **I restore**.","C":"This ordinary when time clause uses a present form, not will.","D":"An -ing form alone is not a finite verb for I in this clause."}}},{"id":"e314f1c5-1f77-52e4-a48d-3d12ac6e0d3c","topicSlug":"future-forms","level":"A2","prompt":"Make a promise with will: I ____ the garden fence tomorrow.","choices":[{"id":"A","text":"will to measure"},{"id":"B","text":"will measuring"},{"id":"C","text":"will measured"},{"id":"D","text":"will measure"}],"answerId":"D","hint":"The instruction asks for a promise with **will**. Check the form immediately after the modal.","explanation":"A promise uses **will + measure**. The modal already marks the future meaning; keep the main verb in its base form.","keywords":["will-form"],"skill":"will-form","contextKey":"future-forms-3","fingerprint":"6c499a393646103abd14b51563b2ba039c37edf2957d0b9b290e9946b9309ef7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The instruction asks for a promise with **will**. Check the form immediately after the modal.","A promise uses **will + measure**. The modal already marks the future meaning; keep the main verb in its base form.","Choose **will measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Will takes a bare infinitive, without to.","B":"An -ing form cannot follow will alone; a continuous form would need be.","C":"A past form cannot directly follow will.","D":"A promise uses **will + measure**. The modal already marks the future meaning; keep the main verb in its base form."}}},{"id":"c06ea18f-443c-5e68-abff-78b9858b7b81","topicSlug":"future-forms","level":"A2","prompt":"Complete the prior plan using going to: We ____ the garden fence next week.","choices":[{"id":"A","text":"going to measure"},{"id":"B","text":"are going to measure"},{"id":"C","text":"is going to measure"},{"id":"D","text":"are going to measuring"}],"answerId":"B","hint":"Find the subject, then build **be going to + base verb**.","explanation":"With **we**, use **are going to + measure** for the stated prior plan.","keywords":["going-to-form"],"skill":"going-to-form","contextKey":"future-forms-3","fingerprint":"93672114b33711dfbb60321dc21761840a75aedb8b566382ff1b5f54be13c683","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the subject, then build **be going to + base verb**.","With **we**, use **are going to + measure** for the stated prior plan.","Choose **are going to measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The finite verb are is missing.","B":"With **we**, use **are going to + measure** for the stated prior plan.","C":"Is does not agree with we.","D":"To in this intention pattern takes the base verb, not -ing."}}},{"id":"f1440c40-3d29-535e-acaf-263ee9aa2da0","topicSlug":"future-forms","level":"A2","prompt":"Use the present continuous for a booked arrangement: She ____ the garden fence on Tuesday.","choices":[{"id":"A","text":"measuring"},{"id":"B","text":"is measuring"},{"id":"C","text":"are measuring"},{"id":"D","text":"is measure"}],"answerId":"B","hint":"A future time can accompany a present continuous arrangement. Check subject + be + -ing.","explanation":"The arrangement is expressed with **is + measuring**; Tuesday gives it future reference.","keywords":["arrangement"],"skill":"arrangement","contextKey":"future-forms-3","fingerprint":"4c8fcaf7b7f57d4cac5bb3b1b0da5a95ab1ccbe987b1826489a617c360de8608","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A future time can accompany a present continuous arrangement. Check subject + be + -ing.","The arrangement is expressed with **is + measuring**; Tuesday gives it future reference.","Choose **is measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The finite auxiliary is is missing.","B":"The arrangement is expressed with **is + measuring**; Tuesday gives it future reference.","C":"Are does not agree with she.","D":"The present continuous needs the -ing form after is."}}},{"id":"3f7f30af-2682-5a47-a574-d29f43579c1d","topicSlug":"future-forms","level":"A2","prompt":"Keep the when-clause in the present simple: I will call when I ____ the garden fence.","choices":[{"id":"A","text":"to measure"},{"id":"B","text":"measure"},{"id":"C","text":"will measure"},{"id":"D","text":"measuring"}],"answerId":"B","hint":"Locate **when**. The future marker belongs in the main clause, while this time clause uses present simple.","explanation":"The ordinary future time clause after **when** uses present simple: **I measure**.","keywords":["future-time-clause"],"skill":"future-time-clause","contextKey":"future-forms-3","fingerprint":"ab34e2f450b70add022a2064594c1238ce7a118239995d6f048fb89e77a69c93","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Locate **when**. The future marker belongs in the main clause, while this time clause uses present simple.","The ordinary future time clause after **when** uses present simple: **I measure**.","Choose **measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An infinitive cannot serve as the finite verb after when I.","B":"The ordinary future time clause after **when** uses present simple: **I measure**.","C":"This ordinary when time clause uses a present form, not will.","D":"An -ing form alone is not a finite verb for I in this clause."}}},{"id":"fca4e6b3-8b1c-58f4-a4fa-dbe799ff6dab","topicSlug":"future-forms","level":"A2","prompt":"Make a promise with will: I ____ the travel leaflet tomorrow.","choices":[{"id":"A","text":"will translating"},{"id":"B","text":"will translated"},{"id":"C","text":"will translate"},{"id":"D","text":"will to translate"}],"answerId":"C","hint":"The instruction asks for a promise with **will**. Check the form immediately after the modal.","explanation":"A promise uses **will + translate**. The modal already marks the future meaning; keep the main verb in its base form.","keywords":["will-form"],"skill":"will-form","contextKey":"future-forms-4","fingerprint":"e715c37e56226b21ccbf1cab8dbbcc9e9a46e5562e07a65f6d693cd43f30f058","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The instruction asks for a promise with **will**. Check the form immediately after the modal.","A promise uses **will + translate**. The modal already marks the future meaning; keep the main verb in its base form.","Choose **will translate**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form cannot follow will alone; a continuous form would need be.","B":"A past form cannot directly follow will.","C":"A promise uses **will + translate**. The modal already marks the future meaning; keep the main verb in its base form.","D":"Will takes a bare infinitive, without to."}}},{"id":"646289a8-211e-5bf5-a0ca-0584d9f52c93","topicSlug":"future-forms","level":"A2","prompt":"Complete the prior plan using going to: We ____ the travel leaflet next week.","choices":[{"id":"A","text":"are going to translating"},{"id":"B","text":"going to translate"},{"id":"C","text":"are going to translate"},{"id":"D","text":"is going to translate"}],"answerId":"C","hint":"Find the subject, then build **be going to + base verb**.","explanation":"With **we**, use **are going to + translate** for the stated prior plan.","keywords":["going-to-form"],"skill":"going-to-form","contextKey":"future-forms-4","fingerprint":"2b14ba1b94b06cfe1b71c6fc5478ebff0470048d09851fc17cf997bf8e791ded","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the subject, then build **be going to + base verb**.","With **we**, use **are going to + translate** for the stated prior plan.","Choose **are going to translate**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"To in this intention pattern takes the base verb, not -ing.","B":"The finite verb are is missing.","C":"With **we**, use **are going to + translate** for the stated prior plan.","D":"Is does not agree with we."}}},{"id":"72693b40-aacc-5e5c-ae9a-f216ee8dd7ec","topicSlug":"future-forms","level":"A2","prompt":"Use the present continuous for a booked arrangement: She ____ the travel leaflet on Tuesday.","choices":[{"id":"A","text":"translating"},{"id":"B","text":"is translating"},{"id":"C","text":"are translating"},{"id":"D","text":"is translate"}],"answerId":"B","hint":"A future time can accompany a present continuous arrangement. Check subject + be + -ing.","explanation":"The arrangement is expressed with **is + translating**; Tuesday gives it future reference.","keywords":["arrangement"],"skill":"arrangement","contextKey":"future-forms-4","fingerprint":"194ffc4b518d85f92642b2daa8115fd24fc295600a6c7e01037a3a3959a0bb3d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-forms"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A future time can accompany a present continuous arrangement. Check subject + be + -ing.","The arrangement is expressed with **is + translating**; Tuesday gives it future reference.","Choose **is translating**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The finite auxiliary is is missing.","B":"The arrangement is expressed with **is + translating**; Tuesday gives it future reference.","C":"Are does not agree with she.","D":"The present continuous needs the -ing form after is."}}},{"id":"3e7fb1a6-4e57-53b5-ae10-8779363cd4c6","topicS